"""Build dependency-free bilingual mod documentation and reproducible example downloads."""
from pathlib import Path
from html import escape
import json
from zipfile import ZipFile, ZIP_DEFLATED

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'website'
BALANCE = json.loads((ROOT / 'assets/balance.json').read_text(encoding='utf-8'))

# Each key has a concrete description; missing/new engine parameters must be documented.
